statement.sql:
insert into mail_dispatcherMessageDetails (MessageDetailId,MessageId, UserId,UserEmailAddress,UserFirstName,UserLastName, SystemBased,TypeOfReciept,BodyTypeCode, DigestFlag,PreferenceTimeTypeCode,ReceiptToList,receiptCCList, receiptBccList, SenderId,SenderEmailAddress,SenderFirstName,SenderLastName, Subject,MessageDate, Attachments,SendAlertFlag,SendContentFlag,CreatedDate) SELECT newid(),msg.MessageId,userLog.UserId, case isnull(luUser.userid,'00000000-0000-0000-0000-000000000000') when '00000000-0000-0000-0000-000000000000' then isnull(ext.email,'') else isnull(luUser.PreferredEmail,'') end as email, case isnull(luUser.userid,'00000000-0000-0000-0000-000000000000') when '00000000-0000-0000-0000-000000000000' then isnull(ext.firstname,'') else isnull(luUser.firstname,'') end as firstname, case isnull(luUser.userid,'00000000-0000-0000-0000-000000000000') when '00000000-0000-0000-0000-000000000000' then isnull(ext.lastname,'') else isnull(luUser.lastname,'') end as lastname, userLog.SystemBased,userLog.TypeOfUser,body.BodyType, isnull(luUser.Digest,0), isnull(luUser.Digest,0), msgLog.ReceiptToList,msgLog.receiptCCList, msgLog.receiptBCCList, msg.SenderId, isnull(SenUser.Email,''),isnull(SenUser.firstName,''),isnull(SenUser.LastName,''), msg.Subject,msg.MessageDate, msg.Attachments, isnull(msg.SendAlertFlag,1), isnull(msg.SendContentFlag,1), current_timestamp FROM mail_message msg join mail_messageLog msgLog on msgLog.MessageId = msg.MessageId join mail_body body on body.MessageId = msg.MessageId join mail_UserLog userLog on userLog.MessageId = msg.MessageId left join lu_users SenUser on msgLog.userid = SenUser.Userid left join lu_users luUser on userlog.Userid = luUser.userid left join Mail_ExternalUsers ext on userlog.Userid = ext.ExternalUserId
userLog.TypeOfUser <> 'From'
;
update mail_dispatchermessagequeue set MessageDetailPopulated = 1
;

DELETE from Mail_DispatcherMessageDetails




;
DELETE from Mail_DispatcherMessageQueue
